-- Subset of Tivra's SQLite schema (read-only contract, docs/research/06-tivra-integration.md section 1.1)
-- plus six 10-minute scenarios. Scenario i starts at BASE + i * 1h, BASE = 1792727400000.
--   0 clean | 1 violation (claude.ai 42 s) | 2 warning (chatgpt flash + phone use) | 3 capture gap | 4 paused span | 5 phone deny package
CREATE TABLE tivra_events (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, ts INTEGER NOT NULL, source TEXT NOT NULL, payload BLOB NOT NULL, device_id TEXT NOT NULL DEFAULT 'mac-local', tz_offset_min INTEGER);
CREATE TABLE activity_spans(
  id INTEGER PRIMARY KEY, device_id TEXT NOT NULL, start_ts INTEGER NOT NULL, end_ts INTEGER NOT NULL,
  kind TEXT NOT NULL, source TEXT NOT NULL, bundle_id TEXT, app_name TEXT, title TEXT, url TEXT, domain TEXT,
  category TEXT, method TEXT NOT NULL, band TEXT NOT NULL);
CREATE TABLE source_health(source TEXT NOT NULL, device_id TEXT NOT NULL, state TEXT NOT NULL, last_ok_ts INTEGER, last_error TEXT, updated_ts INTEGER NOT NULL, PRIMARY KEY (source, device_id));
CREATE TABLE sessions (id TEXT PRIMARY KEY, template_id TEXT, triggered_by TEXT NOT NULL, planned_start_ts INTEGER NOT NULL, actual_start_ts INTEGER, planned_end_ts INTEGER NOT NULL, actual_end_ts INTEGER, final_state TEXT, is_protected BOOLEAN NOT NULL, created_at INTEGER NOT NULL);

